package dns
import("context";"fmt";"math";"time")
type RetryPolicy struct{MaxAttempts uint32 `json:"max_attempts"`;BaseDelay time.Duration `json:"base_delay"`;MaxDelay time.Duration `json:"max_delay"`}
func(p RetryPolicy)Validate()error{if p.MaxAttempts==0{return fmt.Errorf("max attempts must be positive")};if p.BaseDelay<=0||p.MaxDelay<=0{return fmt.Errorf("retry delays must be positive")};if p.BaseDelay>p.MaxDelay{return fmt.Errorf("base delay cannot exceed max delay")};return nil}
func RetryDelay(policy RetryPolicy,attempt uint32)time.Duration{if attempt==0||policy.BaseDelay<=0{return 0};factor:=math.Pow(2,float64(attempt-1));if math.IsInf(factor,0){return policy.MaxDelay};d:=time.Duration(float64(policy.BaseDelay)*factor);if d>policy.MaxDelay||d<0{return policy.MaxDelay};return d}
func ExecuteWithRetry(ctx context.Context,policy RetryPolicy,execute func(context.Context)error)error{if err:=policy.Validate();err!=nil{return err};if ctx==nil{return context.Canceled};if execute==nil{return fmt.Errorf("execute callback is required")};var lastErr error;for attempt:=uint32(1);attempt<=policy.MaxAttempts;attempt++{if err:=ctx.Err();err!=nil{return err};if err:=execute(ctx);err==nil{return nil}else{lastErr=err};if attempt==policy.MaxAttempts{break};timer:=time.NewTimer(RetryDelay(policy,attempt));select{case<-ctx.Done():if !timer.Stop(){<-timer.C};return ctx.Err();case<-timer.C:}};return fmt.Errorf("reconciliation failed after %d attempts: %w",policy.MaxAttempts,lastErr)}
